* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
}

#dashboard {
  max-width: 960px;
  margin: 0 auto;
  padding: 32px 20px 64px;
}

.dashboard-header h1 {
  margin: 0 0 4px;
  font-size: 28px;
}

.subtitle {
  margin: 0 0 24px;
  color: var(--muted);
}

#filter-form {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px;
  margin-bottom: 24px;
}

.filter-fields {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: flex-end;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field label {
  font-size: 13px;
  color: var(--muted);
}

.field input[type="date"] {
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 14px;
}

.field.actions {
  flex-direction: row;
  align-items: center;
  gap: 12px;
}

.field input[type="submit"] {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 9px 18px;
  font-size: 14px;
  cursor: pointer;
}

.clear-link {
  color: var(--accent);
  text-decoration: none;
  font-size: 14px;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-bottom: 32px;
}

.metric-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.metric-label {
  font-size: 13px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.metric-value {
  font-size: 26px;
  font-weight: 700;
}

section h2 {
  font-size: 18px;
  margin: 0 0 16px;
}

.chart-section,
.table-section {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 20px;
  margin-bottom: 24px;
}

#chart {
  display: flex;
  align-items: flex-end;
  gap: 24px;
  min-height: 240px;
  padding: 16px 8px 0;
  border-bottom: 2px solid var(--border);
  overflow-x: auto;
}

.chart-bar {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  flex: 1 1 0;
  min-width: 64px;
  height: 220px;
}

.chart-bar-value {
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 6px;
  white-space: nowrap;
}

.chart-bar-fill {
  width: 100%;
  max-width: 72px;
  min-height: 4px;
  background: linear-gradient(180deg, var(--accent), #60a5fa);
  border-radius: 6px 6px 0 0;
}

.chart-bar-label {
  margin-top: 8px;
  font-size: 13px;
  font-weight: 600;
  text-align: center;
  word-break: break-word;
}

#orders-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

#orders-table th,
#orders-table td {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}

#orders-table thead th {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
}

#orders-table .amount {
  text-align: right;
}

#orders-table tfoot th {
  border-bottom: none;
  border-top: 2px solid var(--border);
}

.empty-state {
  background: var(--card);
  border: 1px dashed var(--border);
  border-radius: 12px;
  padding: 40px 20px;
  text-align: center;
}

.empty-state h2 {
  margin: 0 0 8px;
}

.empty-state p {
  margin: 0;
  color: var(--muted);
}
"}

